export type DisasterMore = {
  summary?: string;
  source?: string;
  glide?: string;
  modified?: string;
  reports?: number;
  at?: [lat: number, lon: number];
  size?: [value: number, unit: string];
  magnitude?: number;
  depthKm?: number;
  shaken?: string;
  tsunamiM?: number;
  map?: string;
};
